class Access(Enum):
    open = 'open'
    shared = 'shared'
    closed = 'closed'


class ProtectionLevel(Enum):
    unknown = 'unknown'
    not_protected = 'not protected'
    Protected_A = 'Protected A'
    Protected_B = 'Protected B'
    Protected_C = 'Protected C'
    other = 'other'


class SecurityClassificationLevel(Enum):
    unclassified = 'unclassified'
    restricted = 'restricted'
    confidential = 'confidential'
    secret = 'secret'
    top_secret = 'top secret'
    other = 'other'
    unknown = 'unknown'


class EthicalIssuesExist(Enum):
    yes = 'yes'
    no = 'no'
    unknown = 'unknown'


class LinkedDmpIdItem(BaseModel):
    type: Type = Field(..., description='type of identifier', example='doi', title='Type')
    registry_uri: Optional[str] = Field(
        None, description='Link to the reference used to identify the linked dmp', title='Registry_uri'
    )
    registry_version: Optional[str] = Field(
        None, description='To indicate the version number or date of the reference', title='Registry_version'
    )
    identifier: str = Field(
        ...,
        description='identifier of the related dmp',
        example='https://doi.org/10.1371/journal.pcbi.1006750',
        title='Identifier',
    )


class LinkedDmpItem(BaseModel):
    linked_dmp_id: List[LinkedDmpIdItem] = Field(..., min_items=1)
    relationship: str = Field(
        ...,
        description='Explain the relationship of the linked dmp with respect to this dmp. Specify which version is authoritative, if applicable. Example: the linked dmp is the working French version of this authoritative dmp',
        example='The linked dmp is the French version of this dmp',
        title='Relationship',
    )
    access_url: Optional[str] = Field(None, description='URL where the linked dmp can be accessed', title='Access_url')
    download_url: Optional[str] = Field(
        None,
        description='URL where the linked dmp can be downloaded',
        example='http://some.repo.../download/...',
        title='Download_url',
    )


class GeneralInfo(BaseModel):
    title: str = Field(..., description='Title of the DMP', example='The most exciting project ever.', title='Title')
    description: Optional[str] = Field(
        None,
        description="To provide any free-form text information on the Data Management Plan (maDMP). It can be a formal statement describing how research data will be managed and documented throughout a research project and the terms regarding the subsequent deposit of the data with a data repository for long-term management and preservation (Library and Archives Canada). DMP's are living documents that outline a project’s plans for research data management. The content, format and length of DMPs depend on the nature of the given research project. DMPs can be developed to guide a single research project or span a multiproject research initiative or longer-term program of research. The DMP submitted at the application stage could, depending on the complexity and duration of the project, be presented as a more high-level outline and then be expanded on throughout the life of the project enabling automatic exchange, integration, and validation of information provided in DMPs. Machine-actonable DMP's (maDMP) are designed to support the exchange of information between systems, to provide basic interoperability between systems producing or consuming maDMPs, acting on behalf of stakeholders involved in the research life cycle (researchers, funders, repository managers, ICT providers, librarians, etc.) and the information represented over the whole DMP lifecycle (Research Data Alliance).\n",
        example="We're finally get our data under control.",
        title='Description',
    )
    dmp_id: DmpId = Field(..., description='Identifier for the DMP itself', title='Dmp_id')
    created: datetime = Field(
        ...,
        description='Date and time of the first version of the maDMP. This date must not be changed in subsequent maDMPs. Each maDMP has a "Created" date and a "Modified" date. The modification date contains a timestamp of the last modification of the maDMP. Given two maDMPs with different modification dates, one can identify which is newer by comparing the timestamps. The same creation date indicates different versions of the same DMP.  Encoded using the relevant ISO 8601 Date and Time <a href="https://www.w3.org/TR/NOTE-datetime">compliant string</a>',
        example='2019-03-13T13:13:00Z',
        title='Created',
    )
    modified: datetime = Field(
        ...,
        description='Indicates maDMP version, so must be set each time the maDMP is modified.  Dates can be used to indicate past and planned actions. Dataset contains issue date that indicates whether the actions are planned or already performed. If the dataset issue date is set in the future (compared to the maDMP modification date), then the actions are planned. If the issue date is set in the past (compared to the maDMP modification date), the actions were performed in the past. Encoded using the relevant ISO 8601 Date and Time <a href="https://www.w3.org/TR/NOTE-datetime">compliant string</a>',
        example='2019-03-13T13:13:00Z',
        title='Modified',
    )
    language: Language = Field(
        ..., description='Language of the DMP expressed using ISO 639-3', example='eng', title='Language'
    )
    access: Optional[Access] = Field(
        None,
        description='OPEN ACCESS: available to anyone based on an open license (e.g., CC0, CC-BY, Open Government License). SHARED ACCESS: Public access with a license that limits use, that is available to anyone under terms and conditions that are not ‘open\' (e.g., CC-BY-NC), shared only with named people or organisations, or via authentication for specific groups that meet certain criteria. CLOSED ACCESS: Internal access only. <a href="https://theodi.org/insights/tools/the-data-spectrum/">theodi.org</a> ; <a href="https://www.alerc.org.uk/uploads/7/6/3/3/7633190/an_introduction_to_open_shared_and_closed_data.pdf">www.alerc.org.uk</a>',
        example='open',
        title='Access',
    )
    protection_level: Optional[ProtectionLevel] = Field(
        None,
        description='Protected information is not classified. Information is "protected" when unauthorized disclosure could reasonably be expected to cause injury to a non-national interest (i.e., an individual interest such as a person or an organization). Protected information is any sensitive information that does not relate to national security and cannot be disclosed under access and privacy legislation because of the potential injury to particular public or private interests. Protection levels: Protected A (Injury to an individual, organization or government), Protected B (Serious injury to an individual, organization or government), Protected C (Extremely grave injury to an individual, organization or government).  <a href="https://www.canada.ca/en/public-services-procurement/services/industrial-security/security-requirements-contracting/safeguarding-equipment-sites-assets-information/levels-security.html#s2">www.canada.ca</a>',
        example='protected A',
        title='Protection_level',
    )
    protection_level_other_nomenclature: Optional[str] = Field(
        None,
        description='To indicate the protection level of the dmp according to the nomenclature found in dmp_protection_level_other_nomenclature',
        title='Protection_level_other_nomenclature',
    )
    protection_level_other_level: Optional[str] = Field(
        None,
        description='To indicate which nomenclature is used to qualify the dmp protection level when "other" was chosen in dmp_protection_level',
        title='Protection_level_other_level',
    )
    security_classification_level: Optional[SecurityClassificationLevel] = Field(
        None,
        description='Security classification that designates the level of protection against access the DMP requires when unauthorized disclosure could reasonably be expected to cause injury to the national interest – defence and maintenance of the social, political and economic stability of the nation. Classification levels: Unclassified, Restricted (disadvantageous to the interests of the nation), Confidential (injury to the national interest), Secret (serious injury to the national interest), Top Secret (exceptionally grave injury to the national interest). "Other" could include, for example: Clearance, Compartmented information, Critical nuclear weapon design information (CNDWI), No foreign dissemination (NOFORN), Official/For official use only, Official sensitive, Originator controlled dissemination (ORCON), Special intelligence, Sensitive but unclassified. <a href="https://www.canada.ca/en/public-services-procurement/services/industrial-security/security-requirements-contracting/safeguarding-equipment-sites-assets-information/levels-security.html#s2">www.canada.ca</a>',
        example='unclassified',
        title='Security_classification_level',
    )
    security_classification_level_other_nomenclature: Optional[str] = Field(
        None,
        description='To indicate the level of the classified information held by the dmp according to the nomenclature found in dmp_security_classification_level_other_nomenclature',
        title='Security_classification_level_other_nomenclature',
    )
    security_classification_level_other_level: Optional[str] = Field(
        None,
        description='To indicate which nomenclature is used to qualify classified information',
        title='Security_classification_level_other_level',
    )
    schema_version: str = Field(
        'v2.6',
        const=True,
        description='The version you are using is v2.6, you should not edit this field.',
        title='Schema_version',
    )
    schema_version_uri: Optional[str] = Field(None, description='DMP schema URI ', title='Schema_version_uri')
    ethical_issues_exist: EthicalIssuesExist = Field(
        ...,
        description='To indicate whether there are ethical issues related to these data. It is the responsibility of the researcher or data steward to be aware of any ethical issues related to the data. Ethical issues vary widely depending on the context.',
        example='yes',
        title='Ethical_issues_exist',
    )
    ethical_issues_description: Optional[str] = Field(
        None,
        description='To describe any existing or potential ethical issues that are not captured in the following related fields: dmp/protection_level, dmp/security_classification_level, dmp/dataset/disposition_planning/legal_issues_description, dmp/dataset/distribution/data_security-privacy_measures, dmp/dataset/distribution/disposition_planning/legal_issues, dmp/dataset/distribution/protection_level, dmp/dataset/distribution/security_classification_level, dmp/dataset/distribution/license/, dmp/dataset/intellectual_property/, dmp/dataset/security_and_privacy/, dmp/indigenous_considerations/. Examples include, but are not limited to: Bias or lacking representation of certain populations; data collected without informed consent; lack of transparency due to absence of clear documentation about data processing, cleaning, or manipulation; the potential impact of the dataset on marginalized groups; potential dual use of the data that could be detrimental to society or specific groups; data that include cultural artifacts or practices that could be used in ways that disrespect cultural values or traditions; failure to recognize the contributions of all parties involved in collecting the data; failure to identify who is accountable for the data.',
        example='There are ethical issues because...',
        title='Ethical_issues_description',
    )
    ethical_issues_report: Optional[str] = Field(
        None,
        description='To indicate, for example, where a protocol from a meeting with an ethical committee can be found, or an IRB (Institutional Review Board) report.',
        example='http://report.location',
        title='Ethical_issues_report',
    )
    linked_dmp: Optional[List[LinkedDmpItem]] = None


class Type2(Enum):
    orcid = 'orcid'
    isni = 'isni'
    openid = 'openid'
    other = 'other'


