    registry_version: Optional[str] = Field(
        None,
        description='To indicate the version number or date when the system was consulted',
        example='2024/12/30',
        title='Registry_version',
    )
    identifier: str = Field(
        ...,
        description='To indicate the specific value of the contributor’s identifier\xa0',
        example='1111-1111-1111-1111',
        title='Identifier',
    )


