class ContributorCountry(BaseModel):
    name: str = Field(
        ...,
        description='The name of the country, as per the ISO standard ISO 3166-1 Codes for the representation of names of countries and their subdivisions – Part 1: Country codes',
        example='United States of America',
        title='Name',
    )
    code: Code = Field(
        ...,
        description='The 2-letter code of the country, as per the ISO standard 3166-1 Codes for the representation of names of countries and their subdivisions – Part 1: Country codes',
        example='US',
        title='Code',
    )


class ContributorProvinceState(BaseModel):
    name: str = Field(
        ...,
        description='The name of the province or state, as per the ISO standard ISO 3166-2  Codes for the representation of names of countries and their subdivisions – Part 2: Country subdivision code',
        example='Quebec',
        title='Name',
    )
    code: str = Field(
        ...,
        description='The 3-letter code of the province or state, as per the ISO standard 3166-2 Codes for the representation of names of countries and their subdivisions – Part 2: Country subdivision code',
        example='QC',
        title='Code',
    )


class AffiliationItem(BaseModel):
    contributor_affiliation_name: str = Field(
        ...,
        description='Name of the organization the contributor is affiliated with',
        example='Transport Canada',
        title='Contributor_affiliation_name',
    )
    contributor_affiliation_id: ContributorAffiliationId = Field(
        ..., description="Details about the organization's ID", title='Contributor_affiliation_id'
    )
    contributor_country: Optional[ContributorCountry] = Field(
        None, description='Country where the organization is located', title='Contributor_country'
    )
    contributor_province_state: Optional[ContributorProvinceState] = Field(
        None,
        description='Province or state of the organization the contributor is affiliated with',
        title='Contributor_province_state',
    )


class ContributorItem(BaseModel):
    name: str = Field(..., description='Name of the contributor', example='Christopher Robin', title='Name')
    role: List[str] = Field(..., min_items=1)
    mbox: Optional[EmailStr] = Field(
        None, description='To provide an E-mail address of the contributor', example='yyyyyy@canada.ca', title='Mbox'
    )
    contributor_id: ContributorId = Field(
        ..., description='Persistent identifier associated with the contributor', title='Contributor_id'
    )
    affiliation: Optional[List[AffiliationItem]] = None
    position: Optional[str] = Field(
        None,
        description='Role or position of the contributor or cited responsible party',
        example='project manager',
        title='Position',
    )
    telephone: Optional[List[float]] = None
    fax: Optional[List[float]] = None
    delivery_point: Optional[str] = Field(
        None,
        description='Enter the street address for the contributor or the cited responsible party',
        example='150 rue McGill, Montreal',
        title='Delivery_point',
    )
    city: Optional[str] = Field(
        None, description='City where the contributor is located', example='Montreal', title='City'
    )
    postal_zip_code: Optional[str] = Field(
        None, description='ZIP or other postal code of the location', example='H8T3F5', title='Postal_zip_code'
    )
    url: Optional[str] = Field(
        None,
        description='On-line information that can be used to contact the contributor or the cited responsible party. This element should be expressed as a URL that will guide the user to further information online. \n',
        example='https://profils-profiles.science.gc.ca/fr/profil/john-doe',
        title='Url',
    )
    hours_of_service: Optional[str] = Field(
        None,
        description='The time period (including time zone) when the contributor or the cited responsible party can be contacted\n',
        example='08:30 - 17:30 UTC+5',
        title='Hours_of_service',
    )


class Status(Enum):
    approved = 'approved'
    rejected = 'rejected'
    submitted = 'submitted'
    not_submitted = 'not submitted'
    not_applicable = 'not applicable'
    unknown = 'unknown'


class Approval(BaseModel):
    status: Status = Field(..., description='Approval status for the DMP', example='approved', title='Status')
    description: Optional[str] = Field(
        None,
        description='To provide any free-form text information on the approval for the DMP',
        example='Need to respond to all required fields',
        title='Description',
    )
    by_mbox: Optional[EmailStr] = Field(
        None, description='Email of the person who approved the maDMP', example='jean.dupont@email.com', title='By_mbox'
    )


class SourceItem(BaseModel):
    type: List[str] = Field(..., min_items=1)
    description: Optional[str] = Field(
        None,
        description='To provide any free-form text information on the funding source for the project',
        title='Description',
    )


class Type4(Enum):
    fundref = 'fundref'
    url = 'url'
    other = 'other'


class FunderId(BaseModel):
    type: Type4 = Field(
        ..., description='To specify what type the funder identifier is.', example='fundref', title='Type'
    )
    registry_uri: Optional[str] = Field(
        None, description='Link to the registry or system used to identify the funder', title='Registry_uri'
    )
    registry_version: Optional[str] = Field(
        None,
        description='To indicate the version number or date when the registry or reference was consulted',
        title='Registry_version',
    )
    identifier: str = Field(
        ...,
        description='To indicate the specific value of the funder’s identifier. It is recommended to use <a href="https://www.crossref.org/services/funder-registry/" target="_blank">CrossRef Funder Registry</a>.',
        title='Identifier',
    )


class FundingStatus(Enum):
    planned = 'planned'
    applied = 'applied'
    granted = 'granted'
    rejected = 'rejected'
    not_applicable = 'not applicable'


class Type5(Enum):
    url = 'url'
    other = 'other'


class GrantId(BaseModel):
    type: Optional[Type5] = Field(
        None, description='To specify what type the grant ID is.', example='url', title='Type'
    )
    registry_uri: Optional[str] = Field(
        None, description='Link to the reference used to identify the grant', title='Registry_uri'
    )
    registry_version: Optional[str] = Field(
        None, description='To indicate the version number or date of the reference', title='Registry_version'
    )
    identifier: str = Field(
        ..., description='To indicate the specific value of the grant ID.', example='12345-987654', title='Identifier'
    )


class FundingItem(BaseModel):
    source: Optional[List[SourceItem]] = None
    funder_id: FunderId = Field(..., description='Identifier associated with the project funder', title='Funder_id')
    funding_status: FundingStatus = Field(
        ..., description='To express different phases of project lifecycle.', example='planned', title='Funding_status'
    )
    grant_id: Optional[GrantId] = Field(None, description='Identifier associated with the grant', title='Grant_id')


class Agreement(BaseModel):
    description: Optional[str] = Field(
        None,
        description='To provide any free-form text information description on the agreement made with the partner organization',
        example='Agrees to gaze at the stars',
        title='Description',
    )
    type: str = Field(
        ...,
        description='Partner organization agreement type (e.g., MOA - Memorandum of Agreement; MOU - Memorandum of Understanding; Indigenous data sharing agreement; BCR-band council resolution; Treaty; collaborative agreement; cooperative agreement; contract; cost-sharing agreement; contractual material; funding collaboration agreement; grant agreement; service level agreement)',
        example='cooperative agreement',
        title='Type',
    )
    agreement_download_url: Optional[str] = Field(
        None,
        description='Download link to the partner organization agreement document ',
        example='http://some.repo.../download/...',
        title='Agreement_download_url',
    )


class PartnerOrganizationId(BaseModel):
    type: Optional[str] = Field(None, description='Partner organization identifier type', title='Type')
    registry_uri: Optional[str] = Field(
        None, description='Link to the reference used to identify the partner organization', title='Registry_uri'
    )
    registry_version: Optional[str] = Field(
        None, description='To indicate the version number or date of the reference', title='Registry_version'
    )
    identifier: Optional[str] = Field(None, description='Partner organization identifier', title='Identifier')


class PartnerOrganizationItem(BaseModel):
    name: Optional[str] = Field(None, description='Name of partner organization.', example='Stargazers', title='Name')
    agreement: Optional[Agreement] = Field(None, description='Partner organization agreement', title='Agreement')
    partner_organization_id: Optional[PartnerOrganizationId] = Field(
        None,
        description='Unique identifier assigned to represent partner organization.',
        title='Partner_organization_id',
    )


class Exist(Enum):
    yes = 'yes'
    no = 'no'
    unknown = 'unknown'


class RedundantBackupsExist(Enum):
    yes = 'yes'
    no = 'no'
    unknown = 'unknown'


class SafeguardingScienceMeasures(BaseModel):
    exist: Exist = Field(
        ...,
        description='To indicate if any measure has have been taken to safeguard the project',
        example='yes',
        title='Exist',
    )
    redundant_backups_exist: RedundantBackupsExist = Field(
        ...,
        description='To indicate if any redundant backup of the source data exists',
        title='Redundant_backups_exist',
    )


class AlgorithmicImpactAssessmentConducted(Enum):
    yes = 'yes'
    no = 'no'
    unknown = 'unknown'


class ProjectItem(BaseModel):
    title: str = Field(..., description='Project title', example='Mission to the sun.', title='Title')
    description: Optional[str] = Field(
        None,
        description="Project abstract providing an overview of the project's goals and scope",
        example='This project aims to analyze the impact of urbanization on local biodiversity by collecting and assessing environmental data from multiple urban centers. Using remote sensing, field observations, and statistical modeling, the study will identify key factors influencing species diversity and habitat loss. The findings will support sustainable urban planning initiatives and inform conservation strategies.',
        title='Description',
    )
    start: Optional[date_aliased] = Field(
        None,
        description='Project start date. Encoded using the relevant ISO 8601 Date <a href="https://www.w3.org/TR/NOTE-datetime">compliant string</a>',
        example='2023-07-20',
        title='Start',
    )
    end: Optional[date_aliased] = Field(
        None,
        description='Project end date. Encoded using the relevant ISO 8601 Date <a href="https://www.w3.org/TR/NOTE-datetime">compliant string</a>',
        example='2025-12-31',
        title='End',
    )
    funding: List[FundingItem]
    partner_organization: Optional[List[PartnerOrganizationItem]] = None
    safeguarding_science_measures: Optional[SafeguardingScienceMeasures] = Field(
        None,
        description='Science is defined broadly to include the natural, health, and social sciences, mathematics, engineering, and technology. Safeguarding science includes safeguarding research partnerships, opensource due diligence, and risk mitigation. Some elements of safeguarding science are recorded elsewhere in the maDMP (e.g., checksum, data access, data security-privacy measures, ethical issues, intellectual property, partner agreement, protection level, retention/disposition planning, security classification, succession plan, versioning). This section should be used for additional information (e.g., description and link to a risk assessment and mitigation plan). For guidance, see: <a href="https://www.oecd.org/content/dam/oecd/en/publications/reports/2022/06/integrity-and-security-in-the-global-research-ecosystem_2bd8511d/1c416f43-en.pdf">www.oecd.org</a>  ;  <a href="https://science.gc.ca/site/science/en/safeguarding-your-research/guidelines-and-tools-implement-research-security/guidance-conducting-open-source-due-diligence/conducting-open-source-due-diligence-safeguarding-research-partnerships">science.gc.ca</a>  ;  <a href="https://science.gc.ca/site/science/en/safeguarding-your-research/guidelines-and-tools-implement-research-security/mitigating-your-research-security-risks">science.gc.ca</a>  ;  <a href="https://science.gc.ca/site/science/en/safeguarding-your-research/guidelines-and-tools-implement-research-security/national-security-guidelines-research-partnerships/national-security-guidelines-research-partnerships-risk-assessment-form">science.gc.ca</a>',
        title='Safeguarding_science_measures',
    )
    succession_plan: Optional[str] = Field(
        None,
        description='Succession plan, or business continuity plan',
        example='No plan, project falls apart when P.I. leaves.',
        title='Succession_plan',
    )
    algorithmic_impact_assessment_conducted: Optional[AlgorithmicImpactAssessmentConducted] = Field(
        None,
        description='To indicate if an algorithmic impact assessment has been conducted related to these data. For example using this <a href="https://www.canada.ca/en/government/system/digital-government/digital-government-innovations/responsible-use-ai/algorithmic-impact-assessment.html">tool</a >',
        example='yes',
        title='Algorithmic_impact_assessment_conducted',
    )
    algorithmic_impact_assessment_conducted_url: Optional[str] = Field(
        None,
        description='Link to the algorithmic impact assessment',
        title='Algorithmic_impact_assessment_conducted_url',
    )
    classification_plan_code: Optional[str] = Field(
        None,
        description="To indicate the code that applies to the project documents in the organization's classification plan or file plan (recordkeeping).",
        example='EC-01-014-160-010',
        title='Classification_plan_code',
    )


class CostDocumentationItem(BaseModel):
    name: str = Field(
        ...,
        description='Title of the external document documenting the  cost',
        example='Project Business Charter',
        title='Name',
    )
    access_url: Optional[str] = Field(
        None,
        description='A URL of that gives access to the costdocumentation. e.g., landing page, feed, SPARQL endpoint. The access URL should be used for the URL of a service or location that can provide access to cost documentation, typically through a Web form, query or API call.',
        example='https://007gc.sharepoint.com/stb/wqmsd/Project.aspx',
        title='Access_url',
    )
    download_url: Optional[str] = Field(
        None,
        description='Download URL to the cost documentation',
        example='https://gc.sharepoint.com/dpmo/projects/project 345 business charter.docx',
        title='Download_url',
    )


class CostItem(BaseModel):
    title: str = Field(
        ...,
        description='To give a title or name to identify the specific cost that is described in this section',
        example='Cloud storage and software',
        title='Title',
    )
    description: Optional[str] = Field(
        None,
        description='To provide additional details about a cost, including specifying which activities or resources it relates to, such as making data FAIR, ensuring data accessibility, or enhancing its reusability.',
        example='Storage and backup costs are calculated based on a 12-month storage period, daily incremental and weekly full backups, and a frequency of 4 restores per month, as outlined in the evaluation table at www.example-storagecostevaluation.com.',
        title='Description',
    )
    value: Optional[float] = Field(
        None, description='Cost value in the specified currency\xa0', example='1,000,000', title='Value'
    )
    cost_documentation: Optional[List[CostDocumentationItem]] = None


class CommunityApprovalItem(BaseModel):
    status: Optional[str] = Field(
        None,
        description='To provide any free-form text information on the project approval from the Indigenous communities.',
        title='Status',
    )


