class IndigenousConsiderations(BaseModel):
    exist: Exist = Field(
        ..., description='To indicate if Indigenous consideration exist.', example='yes', title='Exist'
    )
    community_approval: Optional[List[CommunityApprovalItem]] = None
    group_identification: Optional[List[str]] = None
    government_name: Optional[str] = Field(
        None, description='Indigenous government group affiliated with the contributor', title='Government_name'
    )
    language: Optional[Language1] = Field(
        None,
        description='To indicate if Indigenous language is used. If the answer is "yes," then it is identified under maDMP language and/or Dataset language and/or Distribution language.',
        example='yes',
        title='Language',
    )
    characters: Optional[Characters] = Field(
        None,
        description='To indicate if Indigenous characters are used in the data. If the answer is "yes," then \'Unified Canadian Aboriginal Syllabics Extended\' is identified under distribution/character_unicode_block',
        example='yes',
        title='Characters',
    )
    research_method: Optional[List[str]] = None
    indian_band_name: Optional[List[IndianBandNameEnum]] = None
    indian_band_number: Optional[List[IndianBandNumberEnum]] = None


class Type6(Enum):
    handle = 'handle'
    doi = 'doi'
    ark = 'ark'
    url = 'url'
    other = 'other'


class DatasetId(BaseModel):
    identifier: str = Field(
        ...,
        description='To indicate the specific value of the dataset ID',
        example='University of Vienna Phaidra (univie.ac.at)',
        title='Identifier',
    )
    type: Type6 = Field(..., description='To specify what type the dataset ID is.', example='url', title='Type')
    registry_url: Optional[str] = Field(
        None,
        description='Link to the registry or system used to identify the dataset',
        example='https://ecollab.ncr.int.ec.gc.ca/theme/1275886/DataInventoryProject/Data-Asset-Inventory_Master-Spreadsheet_FINAL.xlsx',
        title='Registry_url',
    )
    registry_version: Optional[str] = Field(
        None,
        description='To indicate the version number or date when the system or registry was consulted',
        example='2024-12-30',
        title='Registry_version',
    )


class SubjectItem(BaseModel):
    heading_name: str = Field(
        ...,
        description='Subject, classification code, or keyword describing the dataset. Privilege subject headings from controlled vocabularies (subject schemes).',
        example='Astronautics and state',
        title='Heading_name',
    )
    heading_uri: Optional[str] = Field(
        None,
        description='The URI of the subject heading value.',
        example='https://id.loc.gov/authorities/subjects/sh85008973.html',
        title='Heading_uri',
    )
    scheme_name: Optional[str] = Field(
        None,
        description='To indicate the name of the subject scheme or classification system from which the subject heading or classification code is drawn (e.g., Government of Canada Core Subject Thesaurus Government of Canada Core Subject Thesaurus <a href="https://open.canada.ca/data/en/dataset/d4a0e406-eea9-41a7-bcae-28c31f3b9c65,">open.canada.ca</a> Canadian Subject Headings <a href="https://library-archives.canada.ca/eng/services/services-libraries/cataloguing/Pages/canadian-subject-headings.aspx,">library-archives.canada.ca</a> Répertoire de vedettes-matière <a href="https://www.bibl.ulaval.ca/la-bibliotheque/repertoire-de-vedettes-matiere-rvm,">www.bibl.ulaval.ca</a> Library of Congress Subject Headings <a href="https://www.loc.gov/aba/publications/FreeLCSH/freelcsh.html#Introduction,">www.loc.gov</a> etc.)',
        example='X̱wi7x̱wa Classification Scheme',
        title='Scheme_name',
    )
    scheme_uri: Optional[str] = Field(
        None,
        description='The URI of the subject scheme. Consider URIs available at <a href="https://id.loc.gov/vocabulary/subjectSchemes.html">id.loc.gov</a>',
        example='https://xwi7xwa-library-10nov2016.sites.olt.ubc.ca/files/2021/06/2018-MODIFIED-DEER-Public-version.pdf',
        title='Scheme_uri',
    )
    scheme_version: Optional[str] = Field(
        None,
        description='Specify the language and/or iteration number of the subject scheme that was used to assign the subject heading.',
        example='Updated 28 March 2018',
        title='Scheme_version',
    )


