class PersonalData(Enum):
    yes = 'yes'
    no = 'no'
    unknown = 'unknown'


class SensitiveData(Enum):
    yes = 'yes'
    no = 'no'
    unknown = 'unknown'


class Required(Enum):
    yes = 'yes'
    no = 'no'
    not_applicable = 'not applicable'
    unknown = 'unknown'


class PrivacyImpactAssessment(BaseModel):
    download_url: Optional[str] = Field(
        None,
        description='A URL that gives access to the privacy impact assessment. The access URL should be used for the URL of a service or location that can provide access to privacy impact assessment, typically through a Web form, query or API call.',
        example='http://some.repo.../download/...',
        title='Download_url',
    )
    required: Required = Field(
        ..., description='To indicate if a privacy impact assessment is required.', example='yes', title='Required'
    )


class SecurityAndPrivacyItem(BaseModel):
    title: str = Field(
        ...,
        description='Provide a title for each requirement or issue listed in the security and privacy section. Titles need to be specific enough to differentiate issues or requirements between them.',
        example='Anonymization of Personally Identifiable Data',
        title='Title',
    )
    description: Optional[str] = Field(
        None,
        description='Description of security or privacy controls',
        example='The dataset undergoes anonymization by applying data masking techniques. Names, addresses, and phone numbers are replaced with pseudonyms or randomly generated identifiers. Specific details, such as exact birthdates, are generalized into age ranges.',
        title='Description',
    )
    privacy_impact_assessment: Optional[PrivacyImpactAssessment] = Field(
        None,
        description='Privacy impact assessment related to the dataset. Government of Canada institutions should refer to <a href="https://www.tbs-sct.canada.ca/pol/doc-eng.aspx?id=18309">www.tbs-sct.canada.ca</a> ',
        title='Privacy_impact_assessment',
    )


class DatasetUpdateFrequency(Enum):
    triennial = 'triennial'
    biennial = 'biennial'
    annual = 'annual'
    semiannual = 'semiannual'
    threeTimesAYear = 'threeTimesAYear'
    quarterly = 'quarterly'
    bimonthly = 'bimonthly'
    monthly = 'monthly'
    semimonthly = 'semimonthly'
    biweekly = 'biweekly'
    threeTimesAMonth = 'threeTimesAMonth'
    weekly = 'weekly'
    semiweekly = 'semiweekly'
    threeTimesAWeek = 'threeTimesAWeek'
    daily = 'daily'
    continuous = 'continuous'
    irregular = 'irregular'


class DatasetSizeUnits(Enum):
    bytes = 'bytes'
    KB___kilobytes = 'KB - kilobytes'
    MB___megabytes = 'MB - megabytes'
    GB___gigabytes = 'GB - gigabytes'
    TB___terabytes = 'TB - terabytes'
    PB___petabytes = 'PB - petabytes'
    EB___exabyte = 'EB - exabyte'
    ZB___zettabyte = 'ZB - zettabyte'
    YB___yottabyte = 'YB - yottabyte'


class Collection(BaseModel):
    description: Optional[str] = Field(
        None, description='To describe the data collection processes', title='Description'
    )
    data_earliest_date: Optional[date_aliased] = Field(
        None,
        description='The earliest date in the case of time series data. Encoded using the ISO 8601 Date  <a href="https://www.w3.org/TR/NOTE-datetime">compliant string</a>',
        example='1973-01-01',
        title='Data_earliest_date',
    )
    data_latest_date: Optional[date_aliased] = Field(
        None,
        description='For time series data, date of the latest data in the series. Encoded using the relevant ISO 8601 Date <a href="https://www.w3.org/TR/NOTE-datetime">compliant string</a>',
        example='2022-12-31',
        title='Data_latest_date',
    )
    dataset_update_frequency: Optional[DatasetUpdateFrequency] = Field(
        None,
        description='The update frequency of the data in the dataset',
        example='7 days',
        title='Dataset_update_frequency',
    )
    dataset_last_updated: Optional[date_aliased] = Field(
        None,
        description='Date when the dataset was last updated. Encoded using the relevant ISO 8601 Date <a href="https://www.w3.org/TR/NOTE-datetime">compliant string</a>',
        example='2023-07-20',
        title='Dataset_last_updated',
    )
    dataset_size: Optional[float] = Field(
        None, description='Size of the dataset from which distributions are derived.', example='5', title='Dataset_size'
    )
    dataset_size_units: Optional[DatasetSizeUnits] = Field(
        None, description='Dataset size units', example='PB - petabytes', title='Dataset_size_units'
    )
    growth_annual_terabytes: Optional[float] = Field(
        None,
        description='The dataset annual growth rate in terabytes per year. Important information needed when planning storage and associated budget',
        title='Growth_annual_terabytes',
    )
    growth_end_date: Optional[date_aliased] = Field(
        None, description='Date on which data collection for this dataset is expected to cease', title='Growth_end_date'
    )


