class DataManagementSystem(BaseModel):
    title: str = Field(
        ...,
        description='Name of the active data management system used to store/process data (e.g., PostgreSQL, MySQL, Dataverse, iRODS, etc.)',
        example='NAQUA',
        title='Title',
    )
    support_checksum: Optional[SupportChecksum] = Field(
        None,
        description='Indicates whether checksum verification is supported',
        example='yes',
        title='Support_checksum',
    )
    type: Type7 = Field(
        ...,
        description="The type of system used to store and manage active data. Note that a time-series database like TimescaleDB is actually a relational database, but because it's optimized for time-series data, it gets its own distinct category",
        example='Relational Database Management System (RDBMS)',
        title='Type',
    )
    access_url: Optional[str] = Field(
        None,
        description='Web or network-accessible URL for accessing the system',
        example='https://dmssystem.org',
        title='Access_url',
    )
    version: Optional[str] = Field(
        None, description='Version of the data management system', example='3.2.1', title='Version'
    )
    description: Optional[str] = Field(
        None,
        description='Brief explanation of the system’s purpose and functionality in relation to this dataset. If relevant, indicate the data types managed by the system.',
        example='During the active phase of the research project, active and transitory data are managed (versioned and tracked) within DBMSX.',
        title='Description',
    )
    certified_with: Optional[str] = Field(
        None,
        description='Certifications relevant to the system (e.g., CoreTrustSeal, ISO 16363).',
        example='coretrustseal',
        title='Certified_with',
    )
    compliance_standards: Optional[List[str]] = None
    protocol: Optional[Protocol] = Field(
        None, description='The protocol used to interact with the system ', example='OAI-PMH', title='Protocol'
    )
    authentication: Optional[List[AuthenticationEnum]] = None
    visibility: Optional[Visibility] = Field(
        None,
        description='Defines whether the data management system is accessible internally within an organization or externally to broader audiences. Allowed values: Internal (accessible only within a specific organization or project), External (accessible to users outside the organization via public or controlled access)',
        example='Internal',
        title='Visibility',
    )
    storage_type: Optional[List[StorageTypeEnum]] = None
    geo_location: Optional[GeoLocation] = Field(
        None,
        description='The geographical location of the server hosting the system expressed using ISO 3166-1 country code.',
        example='CA',
        title='Geo_location',
    )
    availability: Optional[str] = Field(
        None,
        description='Defines whether the system is operational 24/7 or has downtime periods (e.g., 24/7, scheduled downtime)',
        example='scheduled down time',
        title='Availability',
    )
    backup_frequency: Optional[str] = Field(
        None, description='Backup frequency of the system', example='weekly', title='Backup_frequency'
    )
    backup_type: Optional[BackupType] = Field(
        None,
        description='Type of backup performed on the data (e.g., incremental, full, differential, synthetic full)',
        title='Backup_type',
    )
    support_versioning: Optional[SupportVersioning] = Field(
        None,
        description='To indicate if the data management system supports versioning, meaning changes to datasets are tracked internally',
        example='yes',
        title='Support_versioning',
    )
    pid_system: Optional[List[PidSystemEnum]] = None
    data_transfer_maximum_latency: Optional[float] = Field(
        None,
        description='Maximum data transfer latency of the data en ms, i.e. the delay of data transfer ',
        example='50',
        title='Data_transfer_maximum_latency',
    )
    data_transfer_minimum_throughput: Optional[float] = Field(
        None,
        description='Maximum throughput of the dataset in Mbps',
        example='10',
        title='Data_transfer_minimum_throughput',
    )


