class SoftwareManagementPlanItem(BaseModel):
    smp_name: str = Field(..., description='The name or title of the software management plan', title='Smp_name')
    smp_access_url: Optional[str] = Field(
        None,
        description='A URL of that gives access to the Software Management Plan (SMP), e.g., landing page, feed, SPARQL endpoint. The access URL should be used for the URL of a service or location that can provide access to the SMP, typically through a Web form, query or API call.',
        example='some.intranet/.../project page.aspx',
        title='Smp_access_url',
    )
    smp_download_url: Optional[str] = Field(
        None,
        description='Title of the external document documenting the  cost',
        example='http://some.repo.../download/...',
        title='Smp_download_url',
    )


class SoftwareItem(BaseModel):
    description: Optional[str] = Field(
        None,
        description='To provide any free-form text information on the computer code used',
        example='Tool for spatial data analysis',
        title='Description',
    )
    download_url: Optional[str] = Field(
        None, description='the URL to download the computer code or the software', title='Download_url'
    )
    code_repository: Optional[str] = Field(
        None,
        description='Link to a version control repository if applicable',
        example='https://github.com/FAIRERdata/maDMP-Standard',
        title='Code_repository',
    )
    license: Optional[str] = Field(
        None,
        description='The licensing terms under which the software/code is released. Use of a license is highly recommended (e.g., CC BY-SA 4.0, MIT, open government license, etc.)',
        example='CC BY-SA 4.0',
        title='License',
    )
    programming_language: Optional[str] = Field(
        None,
        description='Computer programming language used (e.g., Python, R, SAS)',
        example='Python',
        title='Programming_language',
    )
    dependencies: Optional[List[str]] = None
    operating_system_description: Optional[str] = Field(
        None,
        description='If OS dependent, to provide any free-form text information on the operating system used',
        title='Operating_system_description',
    )
    operating_system_name: Optional[OperatingSystemName] = Field(
        None, description='If OS dependent, operating system used ', example='linux', title='Operating_system_name'
    )
    execution_environment: Optional[str] = Field(
        None,
        description='Specify where the software runs (e.g., Local Machine, Cloud, Docker, Kubernetes, etc.)',
        example='laptop',
        title='Execution_environment',
    )
    proprietary_software: ProprietarySoftware = Field(
        ..., description='To indicate if proprietary software was used', example='yes', title='Proprietary_software'
    )
    software_management_plan: Optional[List[SoftwareManagementPlanItem]] = None


class HardwareRequirements(BaseModel):
    title: str = Field(
        ...,
        description='Identify the purpose requiring specific hardware',
        example='Mapping historical data',
        title='Title',
    )
    description: str = Field(..., description='Describe the hardware requirement', title='Description')
    minimum_cpu_cores: Optional[float] = Field(
        None, description='Minimum CPU cores needed to process the data', example='8', title='Minimum_cpu_cores'
    )
    minimum_cpu_speed: Optional[float] = Field(
        None,
        description='Minimum clock speed needed to process the data in GHz',
        example='2.5 GHz',
        title='Minimum_cpu_speed',
    )
    machine_type: Optional[str] = Field(
        None,
        description='Minimum computing type needed to process the data (e.g., desktop workstation, laptop, server, HPC, super computer)',
        example='HPC',
        title='Machine_type',
    )
    data_processing_minimum_RAM_Gb: Optional[float] = Field(
        None,
        description='Minimum RAM needed to process the data in GB',
        example='16',
        title='Data_processing_minimum_ram_gb',
    )
    storage_capacity: Optional[float] = Field(
        None, description='Minimum storage space required', example='1', title='Storage_capacity'
    )
    processing_unit_requirements: Optional[str] = Field(
        None,
        description='Need for specialized hardware like GPUs/TPUs for computation',
        example='NVIDIA Tesla V100',
        title='Processing_unit_requirements',
    )
    network_requirements: Optional[float] = Field(
        None,
        description='Minimum bandwidth or network speed required in Mbps',
        example='100',
        title='Network_requirements',
    )


class TechnicalResourceItem(BaseModel):
    name: str = Field(..., description='Name of the technical resource', example='123/45/43/AT', title='Name')
    description: Optional[str] = Field(
        None,
        description='List all technical resources (e.g. tools or software) and computing environments required for any stage of a dataset lifecycle (e.g. microscopes, sensors, Jupyter Notebook, Galaxy workflows, measuring devices), and for which documentation is required.',
        title='Description',
    )
    data_management_system: Optional[DataManagementSystem] = Field(
        None,
        description='To describe the database management system or other computerized data system used to store or manage active data. Every other systems used to access the data should be described as distributions.',
        title='Data_management_system',
    )
    software: Optional[List[SoftwareItem]] = None
    hardware_requirements: Optional[HardwareRequirements] = Field(
        None,
        description='Minimum requirements for processing data for a specific purpose',
        title='Hardware_requirements',
    )


