class Contact(BaseModel):
    name: str = Field(
        ..., description='Name of the contact person or organization', example='Winnie Pooh', title='Name'
    )
    mbox: EmailStr = Field(..., description='E-mail address', example='xxxxxx@canada.ca', title='Mbox')
    contact_id: ContactId = Field(
        ..., description='Persistent identifier associated with the contact', title='Contact_id'
    )
    role: Optional[Role] = Field(None, description='Role of the reponsible party.', example='Contact', title='Role')
    telephone: Optional[List[float]] = None
    fax: Optional[List[float]] = None
    position: Optional[str] = Field(
        None,
        description='Position of the contact if contact is a person.',
        example='Senior Systems Scientist',
        title='Position',
    )
    affiliation: Optional[List[AffiliationItem2]] = None
    url: Optional[str] = Field(
        None,
        description='On-line information that can be used to contact the responsible individual or organization. This element should be expressed as a URL that will guide the user to further information online. \n',
        example='www.geogratis.gc.ca',
        title='Url',
    )
    delivery_point: Optional[str] = Field(
        None,
        description='Enter the street address for the responsible organization or individual\n',
        example='2144; King West',
        title='Delivery_point',
    )
    city: Optional[str] = Field(
        None, description='City where the contact is located', example='Sherbrooke', title='City'
    )
    postal_zip_code: Optional[str] = Field(
        None, description='ZIP or other postal code of the location\n', example='J1J 2E8', title='Postal_zip_code'
    )
    hours_of_service: Optional[str] = Field(
        None,
        description='The time period (including time zone) when the organization or individual can be contacted\n',
        example='8:30/12:00; 13:00/16:30 EST',
        title='Hours_of_service',
    )


class Dmp(BaseModel):
    general_info: Optional[GeneralInfo] = Field(None, title='General Information')
    contributor: Optional[List[ContributorItem]] = None
    approval: Optional[Approval] = Field(None, description='Approval of the maDMP', title='Approval')
    project: Optional[List[ProjectItem]] = None
    cost: Optional[List[CostItem]] = None
    indigenous_considerations: Optional[IndigenousConsiderations] = Field(
        None,
        description='Indigenous considerations related to the maDMP or the data.',
        title='Indigenous_considerations',
    )
    dataset: List[DatasetItem] = Field(..., min_items=1)
    contact: Contact = Field(
        ...,
        description='Specifies the party which can provide information about the DMP. This is not necessarily the DMP creator, and it can be a person or an organization.',
        title='Contact',
    )


